def ref(n):  # independent: binary matrix power
    def mul(A,B):
        return ((A[0]*B[0]+A[1]*B[2], A[0]*B[1]+A[1]*B[3]),
                (A[2]*B[0]+A[3]*B[2], A[2]*B[1]+A[3]*B[3]))
    R=(1,0,0,1); M=(1,1,1,0); e=n
